#include "ringbuf.h"
#include <stdlib.h>

struct ringbuf {
    uint8_t *storage; /* internal circular storage */
    size_t   head;    /* next write index (also == end of data) */
    size_t   tail;    /* next read index  (also == start of data) */
    size_t   size;    /* bytes currently stored */
    size_t   capacity;
};

/* ------------------------------------------------------------------ */
ringbuf_t *rb_create(size_t cap)
{
    if (!cap) return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb) return NULL;

    rb->storage = calloc(cap, sizeof(uint8_t));  /* zero-initialise */
    if (!rb->storage) {
        free(rb);
        return NULL;
    }
    rb->head          = 0;
    rb->tail          = 0;
    rb->size          = 0;
    rb->capacity      = cap;
    return rb;
}

/* ------------------------------------------------------------------ */
void rb_destroy(ringbuf_t *rb)
{
    if (!rb) return;              /* spec: NULL is safe */
    free(rb->storage);
    free(rb);
}

/* ------------------------------------------------------------------ */
static void wb_move(ringbuf_t *rb,
                    const uint8_t *src, size_t cnt)
{
    size_t n = rb->capacity - rb->head;     /* bytes to end of array   */
    if (cnt > n) cnt = n;                   /* may only write up to end */
    for (size_t i = 0; i < cnt; ++i)
        rb->storage[rb->head + i] = src[i];
}

/* ------------------------------------------------------------------ */
static void tb_move(uint8_t *dst, const ringbuf_t *rb, size_t cnt)
{
    size_t n = rb->capacity - rb->tail;     /* bytes to end of array   */
    if (cnt > n) cnt = n;
    for (size_t i = 0; i < cnt; ++i)
        dst[rb->tail + i] = rb->storage[rb->tail + i];
}

/* ------------------------------------------------------------------ */
size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data) return 0;
    if (len == 0) return 0;

    /* free-space in the 'head' direction */
    size_t free = rb->capacity - rb->size;
    if (!free) return 0;

    size_t wrote = len > free ? free : len;

    wb_move(rb, data, wrote);
    rb->head   = (rb->head + wrote) % rb->capacity;
    rb->size  += wrote;
    return wrote;
}

/* ------------------------------------------------------------------ */
size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out) return 0;
    if (len == 0) return 0;
    if (!rb->size) return 0;

    size_t avail = rb->size < len ? rb->size : len;

    tb_move(out, rb, avail);
    rb->tail   = (rb->tail + avail) % rb->capacity;
    rb->size  -= avail;
    /* avoid reading from storage that was just "consumed" */
    return avail;
}

/* ------------------------------------------------------------------ */
size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out) return 0;
    if (len == 0) return 0;
    if (!rb->size) return 0;

    size_t avail = rb->size < len ? rb->size : len;

    uint8_t *tmp = malloc(avail);
    if (!tmp) return 0;
    tb_move(tmp, rb, avail);

    /* Copy into destination using the same wrap-aware logic as write */
    size_t remaining = avail;
    const uint8_t *src = tmp;
    while (remaining) {
        size_t n2 = rb->capacity - rb->head + 0;  /* dummy: just copy linearly */
        if (len > 0 && remaining < len) {}         /* already clamped above */
        break;
    }

    for (size_t i = 0; i < avail; ++i)
        out[i] = tmp[i];   /* direct copy, caller provides space */

    free(tmp);
    return avail;
}

/* ------------------------------------------------------------------ */
size_t rb_size(const ringbuf_t *rb)
{
    if (!rb) return 0;
    return rb->size;
}

/* ------------------------------------------------------------------ */
size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb) return 0;
    return rb->capacity;
}

/* ------------------------------------------------------------------ */
void rb_clear(ringbuf_t *rb)
{
    if (!rb) return;
    rb->head = 0;
    rb->tail = 0;
    rb->size = 0;
}

