input.content:
#include "ringbuf.h"
#include <stdlib.h>

struct ringbuf {
    uint8_t *storage;        /* internal circular storage          */
    size_t   head;           /* next write index (== end of data)  */
    size_t   tail;           /* next read index  (== start of data)*/
    size_t   size;           /* bytes currently stored             */
    size_t   capacity;       /* total allocation in bytes          */
};

/* ------------------------------------------------------------------ */
ringbuf_t *rb_create(size_t cap)
{
    if (!cap) return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb) return NULL;

    rb->storage = calloc(cap, sizeof(uint8_t));
    if (!rb->storage) { free(rb); return NULL; }

    rb->head     = 0;
    rb->tail     = 0;
    rb->size     = 0;
    rb->capacity = cap;
    return rb;
}

/* ------------------------------------------------------------------ */
void rb_destroy(ringbuf_t *rb)
{
    if (!rb) return;        /* spec: NULL is allowed */
    free(rb->storage);
    free(rb);
}

/* ------------------------------------------------------------------ */
size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data) return 0;
    if (len == 0) return 0;

    size_t free  = rb->capacity - rb->size;     /* never negative */
    size_t wrote = len > free ? free : len;

    /* first segment: write to end of storage, wrap if we hit the boundary */
    size_t n1 = rb->capacity - rb->head;        /* bytes until end */
    if (wrote > n1) {                             /* must wrap       */
        for (size_t i = 0; i < n1; ++i)
            rb->storage[rb->head + i] = data[i];
        size_t n2 = wrote - n1;                     /* remaining bytes */
        for (size_t i = 0; i < n2; ++i)
            rb->storage[i] = data[n1 + i];
    } else {
        for (size_t i = 0; i < wrote; ++i)
            rb->storage[rb->head + i] = data[i];
    }

    rb->head   = (rb->head + wrote) % rb->capacity;
    rb->size  += wrote;
    return wrote;
}

/* ------------------------------------------------------------------ */
size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out) return 0;
    if (len == 0) return 0;
    if (!rb->size) return 0;

    size_t avail = rb->size < len ? rb->size : len;

    for (size_t i = 0; i < avail; ++i) {
        out[i] = rb->storage[(rb->tail + i) % rb->capacity];
    }
    rb->tail       = (rb->tail + avail) % rb->capacity;
    rb->size      -= avail;
    return avail;
}

/* ------------------------------------------------------------------ */
size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out) return 0;
    if (len == 0) return 0;
    if (!rb->size) return 0;

    size_t avail = rb->size < len ? rb->size : len;

    for (size_t i = 0; i < avail; ++i) {
        out[i] = rb->storage[(rb->tail + i) % rb->capacity];
    }
    return avail;
}

/* ------------------------------------------------------------------ */
size_t rb_size(const ringbuf_t *rb)
{
    if (!rb) return 0;
    return rb->size;
}

/* ------------------------------------------------------------------ */
size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb) return 0;
    return rb->capacity;
}

/* ------------------------------------------------------------------ */
void rb_clear(ringbuf_t *rb)
{
    if (!rb) return;
    rb->head   = 0;
    rb->tail   = 0;
    rb->size   = 0;
}

#include "ringbuf.h"
#include <stdio.h>
#include <string.h>
#include <assert.h>

#define TEST(name) do { printf("  %s ... ", #name); name(); printf("OK\n"); } while(0)
#define ASSERT_EQ(a, b)   do { if ((a) != (b)) { fprintf(stderr, "FAIL: %s == %s\n", #a, #b); exit(1); } } while(0)
#define ASSERT_MEM_EQ(p, q, n)  do { if (memcmp((p),(q),(n)) != 0) { fprintf(stderr, "FAIL: memcmp\n"); exit(1); } } while(0)

static void test_create_destroy(void)
{
    ringbuf_t *rb = rb_create(16);
    ASSERT_EQ(rb_capacity(rb), 16u);
    ASSERT_EQ(rb_size(rb), 0u);
    rb_destroy(rb);
    rb_destroy(NULL);          /* must be safe */
}

static void test_write_full_roundtrip(void)
{
    ringbuf_t *rb = rb_create(8);
    uint8_t in[]  = {1,2,3,4,5,6,7,8};
    uint8_t out[8];
    ASSERT_EQ(rb_write(rb, in, 8), (size_t)8);
    ASSERT_EQ(rb_size(rb), (size_t)8);
    ASSERT_EQ(rb_read(rb, out, 8), (size_t)8);
    ASSERT_MEM_EQ(in, out, 8);
    ASSERT_EQ(rb_size(rb), (size_t)0);
    rb_destroy(rb);
}

static void test_write_wrap(void)
{
    ringbuf_t *rb = rb_create(4);
    uint8_t buf[6];

    /* fill it up */
    ASSERT_EQ(rb_write(rb, (uint8_t*)"\x0a\x0b", 2), (size_t)2);
    ASSERT_EQ(rb_size(rb), (size_t)2);

    drain some so head wraps:
    ASSERT_EQ(rb_read(rb, buf, 1), (size_t)1);   /* remove \x0a */
    ASSERT_EQ(rb_size(rb), (size_t)1);

    now write 4 bytes — they will wrap past capacity
    ASSERT_EQ(rb_write(rb, (uint8_t*)"\x01\x02\x03\x04", 4), (size_t)4);
    ASSERT_EQ(rb_size(rb), (size_t)4);

    read everything back, oldest first
    ASSERT_EQ(rb_read(rb, buf, 4), (size_t)4);
    ASSERT_EQ(buf[0], 0x0b);                       /* next unread after \x0a */
    ASSERT_EQ(buf[1], 0x01);                       /* wraps to storage[0] */
    ASSERT_EQ(buf[2], 0x02);
    ASSERT_EQ(buf[3], 0x03);

    rb_destroy(rb);
}

static void test_write_partial(void)
{
    ringbuf_t *rb = rb_create(3);
    uint8_t in[]  = {1,2,3,4,5};
    ASSERT_EQ(rb_size(rb), (size_t)0);
    ASSERT_EQ(rb_write(rb, in, 5), (size_t)3);   /* only 3 fit */
    ASSERT_EQ(rb_size(rb), (size_t)3);
    rb_destroy(rb);
}

static void test_read_empty(void)
{
    ringbuf_t *rb = rb_create(8);
    uint8_t out[4];
    ASSERT_EQ(rb_read(rb, out, 4), (size_t)0);
    rb_destroy(rb);
}

static void test_peek_no_drain(void)
{
    ringbuf_t *rb = rb_create(8);
    uint8_t in[]  = {10,20,30,40};
    uint8_t peek[4];
    ASSERT_EQ(rb_write(rb, in, 4), (size_t)4);
    ASSERT_EQ(rb_peek(rb, peek, 4), (size_t)4);
    ASSERT_EQ(peek[0], 10u); ASSERT_EQ(peek[3], 40u);
    ASSERT_EQ(rb_size(rb), (size_t)4);           /* peek must not change size */
    rb_destroy(rb);
}

static void test_clear(void)
{
    ringbuf_t *rb = rb_create(4);
    uint8_t in[]  = {1,2};
    ASSERT_EQ(rb_write(rb, in, 2), (size_t)2);
    rb_clear(rb);
    ASSERT_EQ(rb_size(rb), (size_t)0);
    /* can write again */
    uint8_t out[2];
    ASSERT_EQ(rb_write(rb, (uint8_t*)"\x99\xaa", 2), (size_t)2);
    ASSERT_EQ(rb_read(rb, out, 2), (size_t)2);
    ASSERT_MEM_EQ((uint8_t[]){0x99,0xaa}, out, 2);
    rb_destroy(rb);
}

static void test_null_args(void)
{
    ringbuf_t *rb = rb_create(8);
    uint8_t buf[4];
    ASSERT_EQ(rb_write(NULL, buf, 1), (size_t)0);
    ASSERT_EQ(rb_read(NULL, buf, 1), (size_t)0);
    ASSERT_EQ(rb_peek(NULL, buf, 1), (size_t)0);
    ASSERT_EQ(rb_size(NULL), (size_t)0);
    ASSERT_EQ(rb_capacity(NULL), (size_t)0);
    rb_destroy(rb);
}

static void test_capacity_zero(void)
{
    ringbuf_t *rb = rb_create(0);
    ASSERT_EQ((void*)rb, NULL);
}

int main(void)
{
    printf("Running ring buffer tests ...\n\n");
    TEST(test_create_destroy);
    TEST(test_write_full_roundtrip);
    TEST(test_write_wrap);
    TEST(test_write_partial);
    TEST(test_read_empty);
    TEST(test_peek_no_drain);
    TEST(test_clear);
    TEST(test_null_args);
    TEST(test_capacity_zero);
    printf("\nAll tests passed!\n");
    return 0;
}

