#include <string.h>
#include <stdlib.h>

#define TEST(name) do { printf("  %s ... ", #name); name(); printf("OK\n"); } while(0)
#define ASSERT_EQ(a, b)   do { if ((a) != (b)) { fprintf(stderr, "FAIL: %s == %s  (%zu != %zu)\n", #a, #b, (size_t)(a), (size_t)(b)); exit(1); } } while(0)
#define ASSERT_MEM_EQ(p, q, n)   do { if (memcmp((p),(q),(n)) != 0) { fprintf(stderr, "FAIL: memcmp\n"); exit(1); } } while(0)

static void test_create_destroy(void)
{
    ringbuf_t *rb = rb_create(16);
    ASSERT_EQ(rb_capacity(rb), 16u);
    ASSERT_EQ(rb_size(rb), 0u);
    rb_destroy(rb);
    rb_destroy(NULL);          /* spec: NULL is safe */
}

static void test_write_full_roundtrip(void)
{
    ringbuf_t *rb = rb_create(8);
    uint8_t in[]   = {1,2,3,4,5,6,7,8};
    uint8_t out[8];
    ASSERT_EQ(rb_write(rb, in, 8), (size_t)8);
    ASSERT_EQ(rb_size(rb), (size_t)8);
    ASSERT_EQ(rb_read(rb, out, 8), (size_t)8);
    ASSERT_MEM_EQ(in, out, 8);
    ASSERT_EQ(rb_size(rb), (size_t)0);
    rb_destroy(rb);
}

static void test_wrap_write(void)
{
    /* capacity=4. We want to show data wraps from end-of-storage back to index 0 */

    ringbuf_t *rb = rb_create(4);
    uint8_t buf[16];

    /* Step 1 - write 8 bytes: fills [A][B] at indices 0,1;
     *          then [C][D][E][F] wraps to indices 2,3,0,1 */
    ASSERT_EQ(rb_write(rb, (uint8_t[]){'A','B','C','D','E','F','G','H'}, 8), (size_t)4);

    /* Step 2 - read 6 bytes: A,B,C,D,E,F */
    ASSERT_EQ(rb_read(rb, buf, 6), (size_t)6);
    for (int i = 0; i < 6; ++i) {
        ASSERT_EQ(buf[i], (uint8_t)('A' + i));
    }

    /* Step 3 - read remaining bytes */
    uint8_t extra[4];
    size_t n = rb_read(rb, extra, 4);
    ASSERT_EQ(n, (size_t)2);
    ASSERT_EQ(extra[0], (uint8_t)'G');
    ASSERT_EQ(extra[1], (uint8_t)'H');
    ASSERT_EQ(rb_size(rb), (size_t)0);

    rb_destroy(rb);
}

