    ASSERT_EQ(rb_size(rb), (size_t)0);
    ASSERT_EQ(rb_write(rb, in, 5), (size_t)3);   /* only 3 fit */
    ASSERT_EQ(rb_size(rb), (size_t)3);

    uint8_t out[4];
    ASSERT_EQ(rb_read(rb, out, 4), (size_t)3);
    ASSERT_MEM_EQ(in, out, 3);
    ASSERT_EQ(rb_size(rb), (size_t)0);
    rb_destroy(rb);
}

