{
    ringbuf_t *rb = rb_create(8);
    uint8_t out[4];
    ASSERT_EQ(rb_read(rb, out, 4), (size_t)0);
    rb_destroy(rb);
}

static void test_peek_no_drain(void)
{
    ringbuf_t *rb = rb_create(8);
    uint8_t in[]   = {10,20,30,40};
    uint8_t peek[4];
    ASSERT_EQ(rb_write(rb, in, 4), (size_t)4);
