    ASSERT_EQ(peek[0], 10u);  ASSERT_EQ(peek[3], 40u);
    ASSERT_EQ(rb_size(rb), (size_t)4);   /* peek must not change size */
    rb_destroy(rb);
}

static void test_clear(void)
{
    ringbuf_t *rb = rb_create(4);
    uint8_t in[]   = {1,2};
    ASSERT_EQ(rb_write(rb, in, 2), (size_t)2);
    rb_clear(rb);
    ASSERT_EQ(rb_size(rb), (size_t)0);

    /* can write again from scratch */
    uint8_t out[2];
    uint8_t expected[] = {0x99, 0xaa};
    ASSERT_EQ(rb_write(rb, expected, 2), (size_t)2);
    ASSERT_EQ(rb_read(rb, out, 2), (size_t)2);
    ASSERT_MEM_EQ(expected, out, 2);
    rb_destroy(rb);
}

static void test_null_args(void)
{
    ringbuf_t *rb = rb_create(8);
    uint8_t buf[4];
    ASSERT_EQ(rb_write(NULL,       buf, 1), (size_t)0);
    ASSERT_EQ(rb_read(NULL,        buf, 1), (size_t)0);
    ASSERT_EQ(rb_peek(NULL,        buf, 1), (size_t)0);
    ASSERT_EQ(rb_size(NULL),       (size_t)0);
    ASSERT_EQ(rb_capacity(NULL),   (size_t)0);
    rb_destroy(rb);
}

static void test_capacity_zero(void)
{
    ringbuf_t *rb = rb_create(0);
    ASSERT_EQ((void*)rb, NULL);
}

